async function garantirTp(){let tp=null; try{tp=localStorage.getItem('chamae_tp')}catch(_){} if(tp) return tp; try{const sg=await api('segredos?select=valor&chave=eq.senha_equipe'); if(sg[0]){localStorage.setItem('chamae_tp',sg[0].valor); return sg[0].valor}}catch(e){} return null}
/* Marluvas e Medix usam a tela dos conversores (grade, níveis, tabelas) dentro do Sistema; orc = orçamento da base para reabrir nele */
async function abrirApp(rep,orc){if(!EXTERNAL[rep]) return; let ov=document.getElementById('appOv-'+rep);
  if(ov&&orc){try{ov.querySelector('iframe').contentWindow.postMessage({t:'chamae-abrir-orc',id:orc},location.origin)}catch(e){}}
  if(ov){try{ov.querySelector('iframe').contentWindow.postMessage({t:'chamae-produtos'},location.origin)}catch(e){}} /* conversor já aberto: puxa de novo os produtos alterados aqui no Sistema */
  if(!ov) await garantirTp();
  if(!ov){ov=document.createElement('div'); ov.id='appOv-'+rep; ov.className='appov'; ov.style.cssText='position:fixed;inset:0;z-index:35;background:var(--bg);display:flex;flex-direction:column';
    ov.innerHTML=`<div style="display:flex;align-items:center;gap:10px;padding:calc(env(safe-area-inset-top,0px) + 6px) 12px 6px;background:#1c2340;color:#fff"><button class="btn sm" data-fechaapp>‹ Início</button><b style="font-family:var(--display);font-size:18px;text-transform:uppercase;letter-spacing:.03em">${esc(repName(rep))}</b></div><iframe title="${esc(repName(rep))}" src="${EXTERNAL[rep]}?inapp=1${orc?'&orc='+encodeURIComponent(orc):''}" style="flex:1;border:0;width:100%;background:#fff"></iframe>`;
    document.body.appendChild(ov)}
  document.querySelectorAll('.appov').forEach(o=>o.style.display='none'); ov.style.display='flex'; try{history.pushState({app:rep},'')}catch(e){}}
function fecharApp(){document.querySelectorAll('.appov').forEach(o=>o.style.display='none')}
const voltarInicio=()=>fecharApp(); /* sem history.back(): o histórico do app aberto dentro não pode ser desfeito por engano */
addEventListener('popstate',fecharApp);
const SUJO={}; /* conversor avisa quando o orçamento tem alterações não salvas */
const repDoFrame=w=>{const o=[...document.querySelectorAll('.appov')].find(x=>{const f=x.querySelector('iframe'); return f&&f.contentWindow===w}); return o?o.id.replace('appOv-',''):''};
addEventListener('message',e=>{if(e.origin!==location.origin||!e.data) return; if(e.data.t==='chamae-sujo'){const r=repDoFrame(e.source); if(r) SUJO[r]=!!e.data.v; return} if(e.data.t==='chamae-home') sairApp()});
function sairApp(){const ov=[...document.querySelectorAll('.appov')].find(o=>o.style.display!=='none'); const rep=ov?ov.id.replace('appOv-',''):'';
  if(rep&&SUJO[rep]&&confirm('O orçamento '+repName(rep)+' tem alterações não salvas.\n\nOK = salvar e sair\nCancelar = sair sem salvar (ele continua em andamento no '+repName(rep)+')')){try{ov.querySelector('iframe').contentWindow.postMessage({t:'chamae-salvar'},location.origin)}catch(e){}}
  voltarInicio()}
