async function escolherCtPdf(cli){const P=await api(`cliente_pessoas?select=*&cnpj=eq.${cli.cnpj}&order=principal.desc,nome`).catch(()=>[]); const sel=new Set((cli.ct||[]).map(x=>x.id));
  return new Promise(res=>{const ov=document.createElement('div'); ov.className='ov'; ov.style.zIndex=60;
    ov.innerHTML=`<div class="sh grid"><b>Contato no PDF deste orçamento</b>${P.length?P.map(p=>`<label class="row" style="gap:8px;flex-wrap:nowrap"><input type="checkbox" data-ck="${p.id}"${sel.has(p.id)?' checked':''} style="width:20px;height:20px"><span><b>${esc(p.nome)}</b>${p.cargo?` <span class="hint">· ${esc(p.cargo)}</span>`:''}<br><span class="hint">${[p.telefone||p.whatsapp,p.email].filter(Boolean).map(esc).join(' · ')||'sem telefone/e-mail'}</span></span></label>`).join(''):'<p class="hint">Nenhum contato cadastrado. Cadastre na ficha do cliente (aba Contatos).</p>'}<p class="hint" style="margin:0">Vale só para este orçamento. O padrão do cliente se marca na ficha, aba Contatos (📄).</p><div class="row"><button class="btn" data-ok>Aplicar</button><button class="btn ghost" data-x>Cancelar</button></div></div>`; document.body.appendChild(ov);
    ov.onclick=e=>{if(e.target===ov||e.target.closest('[data-x]')){ov.remove(); return res(null)} if(e.target.closest('[data-ok]')){const ids=new Set([...ov.querySelectorAll('[data-ck]:checked')].map(x=>+x.dataset.ck)); ov.remove(); res(P.filter(p=>ids.has(p.id)).map(ctPdf))}}})}

