  const mode=t.mode||'dl'; if(mode==='blob') return {blob,fname}; const canFile=mode!=='dl'&&(mode!=='wa'||MOVEL)&&navigator.canShare&&navigator.canShare({files:[file]});
  const share=()=>navigator.share({files:[file],title:subj,text:body}); const waLink=()=>{const ph=c&&c.tel?String(c.tel).replace(/\D/g,''):''; return (ph.length>=10?`https://wa.me/55${ph}`:'https://wa.me/')+'?text='+encodeURIComponent(body)};
