/*ANEXOS-INICIO*/ /* anexos do orçamento (ordem de compra, fotos, PDFs…): Supabase Storage, bucket 'arquivos', pasta orcamentos/<id do orçamento na base>/ — mesmo código no Sistema e nos conversores */
const ANX={sb:'https://jmpvmyyokikpwphwylob.supabase.co',key:'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImptcHZteXlva2lrcHdwaHd5bG9iIiwicm9sZSI6ImFub24iLCJpYXQiOjE3OTIyMTc1MzEsImV4cCI6MjEwNzc5MzUzMX0.e5XT2R7eOj3x-ZYcRFkY4OFg0QEr3_guxT6-W0xpnfY',cache:{},max:30*1024*1024};
const anxEsc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const anxPasta=id=>'orcamentos/'+String(id).replace(/[^\w.-]+/g,'_')+'/';
const anxTam=b=>!b?'':b<1024*1024?Math.max(1,Math.round(b/1024))+' KB':(b/1024/1024).toFixed(1).replace('.',',')+' MB';
async function anxHdr(){const t=await (window.anxToken?window.anxToken():null); if(!t) throw new Error('Entre com seu login para usar anexos'); return {apikey:ANX.key,Authorization:'Bearer '+t}}
async function anxListar(id,forca){const c=ANX.cache[id]; if(c&&!forca&&Date.now()-c.em<30000) return c.l;
  const h=await anxHdr(); const p=anxPasta(id); const r=await fetch(ANX.sb+'/storage/v1/object/list/arquivos',{method:'POST',headers:{...h,'Content-Type':'application/json'},body:JSON.stringify({prefix:p,limit:200,offset:0,sortBy:{column:'name',order:'asc'}})});
  if(!r.ok) throw new Error((await r.text()).slice(0,150)); const j=await r.json();
  const l=(j||[]).filter(x=>x.id&&x.name&&x.name!=='.emptyFolderPlaceholder').map(x=>({nome:x.name.replace(/^\d{10,}-/,''),caminho:p+x.name,tam:x.metadata&&x.metadata.size,tipo:(x.metadata&&x.metadata.mimetype)||'',em:x.created_at}));
  const im=l.filter(a=>/^image\//.test(a.tipo)||/\.(jpe?g|png|gif|webp)$/i.test(a.nome));
  if(im.length){try{const s=await fetch(ANX.sb+'/storage/v1/object/sign/arquivos',{method:'POST',headers:{...h,'Content-Type':'application/json'},body:JSON.stringify({expiresIn:3600,paths:im.map(a=>a.caminho)})}); const sj=s.ok?await s.json():[]; (sj||[]).forEach(x=>{const a=im.find(y=>y.caminho===x.path); if(a&&x.signedURL) a.mini=ANX.sb+'/storage/v1'+x.signedURL})}catch(e){}}
  ANX.cache[id]={em:Date.now(),l}; return l}
async function anxEnviar(id,files,st){const h=await anxHdr(); let n=0;
  for(const f of files){if(f.size>ANX.max){alert(`"${f.name}" tem ${anxTam(f.size)}. O limite é 30 MB por arquivo.`); continue}
    if(st) st.textContent='Enviando '+f.name+'…';
    const nm=(f.name||'arquivo').normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^\w.-]+/g,'_').slice(-90)||'arquivo';
    const r=await fetch(ANX.sb+'/storage/v1/object/arquivos/'+anxPasta(id)+Date.now()+'-'+nm,{method:'POST',headers:{...h,'Content-Type':f.type||'application/octet-stream','x-upsert':'true'},body:f});
    if(!r.ok) throw new Error((await r.text()).slice(0,150)); n++}
  delete ANX.cache[id]; return n}
async function anxAbrir(caminho){const w=window.open('','_blank'); try{const h=await anxHdr(); const r=await fetch(ANX.sb+'/storage/v1/object/sign/arquivos/'+caminho,{method:'POST',headers:{...h,'Content-Type':'application/json'},body:JSON.stringify({expiresIn:3600})}); const j=await r.json(); if(!j.signedURL) throw new Error('arquivo indisponível'); const u=ANX.sb+'/storage/v1'+j.signedURL; if(w) w.location.href=u; else location.href=u}catch(e){if(w) w.close(); (window.anxToast||alert)('Não consegui abrir: '+e.message)}}
async function anxApagar(id,caminho){const h=await anxHdr(); const r=await fetch(ANX.sb+'/storage/v1/object/arquivos/'+caminho,{method:'DELETE',headers:h}); if(!r.ok) throw new Error((await r.text()).slice(0,150)); delete ANX.cache[id]}
/* monta o quadro de anexos dentro de box. op.id() devolve o id do orçamento na base (ou null se ainda não existe); op.garantir() (opcional, async) salva o orçamento e devolve o id */
function anxMontar(box,op){if(!box) return; const T=window.anxToast||(m=>alert(m));
  box.innerHTML=`<div style="border:1px dashed rgba(127,127,127,.55);border-radius:12px;padding:10px 12px;margin:10px 0;display:grid;gap:8px">
   <div style="display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap"><b>📎 Anexos <span data-anxn style="font-weight:400;opacity:.7"></span></b><small style="opacity:.7">Ordem de compra, fotos, PDFs, planilhas…</small></div>
   <div data-anxl style="display:grid;gap:6px"></div>
   <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center"><label class="btn ghost sm" style="cursor:pointer;display:inline-flex;align-items:center;gap:4px;width:auto">📎 Anexar arquivo<input type="file" multiple data-anxf style="display:none"></label><label class="btn ghost sm" style="cursor:pointer;display:inline-flex;align-items:center;gap:4px;width:auto">📷 Tirar foto<input type="file" accept="image/*" capture="environment" data-anxf style="display:none"></label><small data-anxs style="opacity:.75"></small></div></div>`;
  const L=box.querySelector('[data-anxl]'), N=box.querySelector('[data-anxn]'), S=box.querySelector('[data-anxs]'); let atual=[];
  const pinta=l=>{atual=l; N.textContent=l.length?'('+l.length+')':''; L.innerHTML=l.length?l.map((a,i)=>`<div style="display:flex;align-items:center;gap:8px;min-width:0">
      ${a.mini?`<img src="${anxEsc(a.mini)}" alt="" data-anxo="${i}" style="width:44px;height:44px;object-fit:cover;border-radius:6px;cursor:pointer;flex:none;background:#fff">`:`<span data-anxo="${i}" style="width:44px;height:44px;display:flex;align-items:center;justify-content:center;font-size:22px;border-radius:6px;background:rgba(127,127,127,.15);cursor:pointer;flex:none">${/pdf/i.test(a.tipo)||/\.pdf$/i.test(a.nome)?'📄':/sheet|excel|csv/i.test(a.tipo)||/\.(xlsx?|csv)$/i.test(a.nome)?'📊':'📎'}</span>`}
      <a href="#" data-anxo="${i}" style="flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:inherit">${anxEsc(a.nome)}<br><small style="opacity:.65">${anxTam(a.tam)}${a.em?' · '+new Date(a.em).toLocaleDateString('pt-BR'):''}</small></a>
      <button type="button" class="btn ghost sm" data-anxd="${i}" title="Apagar anexo" aria-label="Apagar anexo" style="width:auto;flex:none">✕</button></div>`).join(''):'<small style="opacity:.65">Nenhum anexo ainda.</small>'};
  const carrega=async forca=>{const id=op.id(); if(!id){pinta([]); return} try{const l=await anxListar(id,forca); if(op.id()===id) pinta(l)}catch(e){L.innerHTML=`<small style="opacity:.7">${anxEsc(/login/.test(e.message)?e.message:'Não consegui listar os anexos agora.')}</small>`}};
  box._anxCarrega=carrega; carrega();
  box.addEventListener('click',async e=>{const o=e.target.closest('[data-anxo]'); if(o){e.preventDefault(); e.stopPropagation(); const a=atual[+o.dataset.anxo]; if(a) anxAbrir(a.caminho); return}
    const d=e.target.closest('[data-anxd]'); if(d){e.preventDefault(); e.stopPropagation(); const a=atual[+d.dataset.anxd]; if(!a||!confirm(`Apagar o anexo "${a.nome}"?`)) return; try{await anxApagar(op.id(),a.caminho); T('Anexo apagado'); carrega(true)}catch(err){T('Erro ao apagar: '+err.message)} return}
    if(e.target.closest('label')) e.stopPropagation()});
  box.querySelectorAll('[data-anxf]').forEach(inp=>inp.addEventListener('change',async e=>{const fs=[...e.target.files]; e.target.value=''; if(!fs.length) return;
    try{let id=op.id(); if(!id&&op.garantir) id=await op.garantir(); if(!id) return T('Salve o orçamento antes de anexar');
      const n=await anxEnviar(id,fs,S); S.textContent=''; if(n) T(n>1?n+' anexos guardados':'Anexo guardado'); carrega(true)}catch(err){S.textContent=''; T('Erro ao anexar: '+err.message)}}));
}
