async function salvar(o,total,sit,rows){await garantirNumero(o); const linhas=(rows||[]).map(r=>({cod:r.p.cod,desc:r.p.descricao,qt:r.i.qt,pu:r.pu,ipi:r.p.ipi,ean:r.p.attrs&&r.p.attrs.ean,ncm:r.p.ncm,ptab:r.ptab,neg:r.i.neg||undefined,plista:r.db?r.plista:undefined,descs:r.db&&(r.i.dc||r.i.dp)?[r.i.dc?'comercial '+r.db.com+'%':'',r.i.dp?'pagamento '+r.db.pag+'%':''].filter(Boolean).join(' + '):undefined,lt:r.lt||undefined,camp:r.camp?{nome:r.camp.nome,fim:r.camp.fim,de:r.ptab0}:undefined,gq:gradeTxt(r.i.gq)?r.i.gq:undefined,sd:o.rep==='sigma'&&SGS[r.p.cod]&&SGS[r.p.cod].it?SGS[r.p.cod].it.disp:undefined})); const body={id:o.sid||(o.sid=sess.uid.slice(0,8)+'-'+o.rep+'-'+o.id),app:o.rep,cliente:o.cli&&o.cli.n,cnpj:o.cli&&o.cli.cnpj,total:Math.round(total*100)/100,itens:o.itens.length,situacao:sit,dados:{...o,linhas},atualizado_em:new Date().toISOString()}; if(o.status) body.status=o.status; saveQ(o); try{await api('orcamentos?on_conflict=id',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify(body)})}catch(e){toast('Salvo no aparelho; sincroniza depois')} if(sit==='enviado') followUpOrc(o,total); if(sit==='enviado'&&o.rep==='sigma'&&SIGMA_AUTO){if(!(o.sigma&&o.sigma.orv)) enviarSigma({id:body.id,dados:body.dados},false,true,o); else if(o.sigma.ass&&o.sigma.ass!==sgAss(linhas)) toast(`Atenção: o orçamento mudou depois de ir para a Sigma (${o.sigma.orv}). Use Reenviar em Pedidos.`)} if(o.status==='cancelado'||o.status==='transmitido') fecharFollowUps(o.sid,stLbl(o.status))}

