   <div class="row" style="margin-bottom:10px">${[['d','Dados'],['c','Políticas comerciais'],['p','Prazos de pagamento ('+pzs.length+')'],['i','Contatos internos ('+cts.length+')'],['a','Arquivos ('+arqs.length+')'],...(id?[['f','📄 PDF do orçamento'],['k','🔥 Campanhas']]:[])].map(([k,l],i)=>`<button class="chip${i===0?' on':''}" data-rt="${k}">${l}</button>`).join('')}</div>
