/* ================= botão Sincronizar Reprio ================= */
async function sincronizarReprio(btn){if(!RK()){toast('Coloque a chave do Reprio em Mais › Ajustes'); return go('aj')} const lb=btn?btn.textContent:''; if(btn){btn.disabled=true; btn.textContent='Sincronizando…'}
  try{const d=new Date(); d.setDate(d.getDate()-120); LIVE=null; const r=await reprioAoVivo(ymd(d),true);
    if(r.gravou){try{await api('rpc/atualizar_resumos',{method:'POST',body:'{}'})}catch(e){}}
    STALE.add('clis3'); delete CLIM.c; CLIS=null; PEDS=null; kv.set('peds3',null); for(const k in MEMO) delete MEMO[k];
    toast(r.gravou?`✓ ${r.rows.length} pedidos/orçamentos dos últimos 120 dias atualizados do Reprio`:r.erro?'Li o Reprio, mas não gravei: '+r.erro:`Li ${r.rows.length} pedidos do Reprio (para gravar na base é preciso ser gestor)`)}
  catch(e){toast('Reprio: '+e.message)} if(btn){btn.disabled=false; btn.textContent=lb}}

/* ================= Ficha do cliente: tabela e prazo habitual em cada representada (o orçamento já abre com eles) ================= */
async function condCliente(cnpj){const box=$('#ctpbox'); if(!box) return; if(!cnpj){box.innerHTML='<p class="hint">Salve o cadastro primeiro.</p>';return}
  const R=(await reps()).filter(r=>r.ativa); const [CT,TA,PD]=await Promise.all([api(`cliente_tabela?select=*&cnpj=eq.${cnpj}`).catch(()=>[]),api('tabelas?select=id,rep,nome,ativa&ativa=eq.true&order=nome').catch(()=>[]),api(`pedidos?select=representada,prazo,tabela,data&cnpj=eq.${cnpj}&or=(status.is.null,status.in.(finalizado,para_transmitir),status.ilike.aprovado*)&order=data.desc&limit=200`).catch(()=>[])]);
  if(!box.isConnected) return; const cfg={}; CT.forEach(c=>cfg[c.rep]={tabela_id:c.tabela_id,prazo:c.prazo||'',prazos:c.prazos||[]});
  const ult={}; PD.forEach(p=>{const r=REPID[p.representada]||Object.keys(HIST_REP).find(k=>HIST_REP[k]===p.representada); if(r&&!ult[r]) ult[r]=p});
  const tabDe=(r,nome)=>{const n=norm(nome||'').replace(/^TABELA\s+/,'').trim(); return n?TA.find(t=>t.rep===r&&norm(t.nome).replace(/^TABELA\s+/,'').trim()===n):null};
  const card=r=>{const T=TA.filter(t=>t.rep===r.id); const c=cfg[r.id]||{}; const u=ult[r.id]; const pzs=[...new Set([...((r.regras||{}).prazos||[]).map(p=>p.n),'A VISTA','28','28/35','28/42','28/35/42','28/42/56','30/45/60','30/60/90'])];
    return `<div class="card grid" style="background:var(--surface2)" data-tp="${r.id}"><div class="row" style="justify-content:space-between"><b>${repIcon(r,22)} ${esc(r.nome)}</b>${c.tabela_id||c.prazo?'<span class="tag ok">cadastrado</span>':''}</div>
     <div class="r2"><label class="f">Tabela de preço${T.length?`<select data-tpt="${r.id}"><option value="">— automática (último pedido) —</option>${T.map(t=>`<option value="${t.id}"${c.tabela_id==t.id?' selected':''}>${esc(t.nome)}</option>`).join('')}</select>`:'<span class="hint">Nenhuma tabela cadastrada para esta fábrica.</span>'}</label>
     <label class="f">Prazo habitual${c.prazo?' · médio '+esc(pzmTxt(c.prazo)):''}<input data-tpp="${r.id}" list="tpl_${r.id}" value="${esc(c.prazo||'')}" placeholder="ex.: 28/42/56"><datalist id="tpl_${r.id}">${pzs.map(x=>`<option value="${esc(x)}">`).join('')}</datalist></label></div>
     ${u?`<div class="row hint" style="justify-content:space-between">Último pedido ${esc(String(u.data||'').split('-').reverse().join('/'))}: prazo ${esc(u.prazo||'—')} · tabela ${esc(u.tabela||'—')}${(u.prazo&&u.prazo!==c.prazo)||(tabDe(r.id,u.tabela)&&tabDe(r.id,u.tabela).id!=c.tabela_id)?`<button class="chip" data-tpu="${r.id}">Usar estes</button>`:''}</div>`:''}</div>`};
  const usa=R.filter(r=>ult[r.id]||cfg[r.id]), outras=R.filter(r=>!usa.includes(r));
  box.innerHTML=`<p class="hint" style="margin:0">Ao escolher este cliente num orçamento, a tabela e o prazo daqui entram sozinhos (dá para trocar no orçamento). Salva ao mudar o campo. Sem tabela marcada, o sistema usa a do último pedido.</p>
   <div class="dgrid">${usa.map(card).join('')||'<p class="hint">Este cliente ainda não comprou de nenhuma representada.</p>'}</div>
   ${outras.length?`<details><summary class="hint" style="cursor:pointer">Outras representadas (${outras.length})</summary><div class="dgrid" style="margin-top:8px">${outras.map(card).join('')}</div></details>`:''}`;
  const salvar=async rep=>{const c=cfg[rep]=cfg[rep]||{}; try{if(!c.tabela_id&&!c.prazo&&!(c.prazos||[]).length) await api(`cliente_tabela?cnpj=eq.${cnpj}&rep=eq.${rep}`,{method:'DELETE'}); else await api('cliente_tabela?on_conflict=cnpj,rep',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({cnpj,rep,tabela_id:c.tabela_id||null,prazo:c.prazo||null,atualizado_em:new Date().toISOString()})}); toast('Salvo')}catch(err){toast('Erro: '+err.message)}};
  box.onchange=async e=>{const t=e.target; const st=t.closest('[data-tpt]'); if(st){const c=cfg[st.dataset.tpt]=cfg[st.dataset.tpt]||{}; c.tabela_id=st.value?+st.value:null; await salvar(st.dataset.tpt); return condCliente(cnpj)}
    const sp=t.closest('[data-tpp]'); if(sp){const c=cfg[sp.dataset.tpp]=cfg[sp.dataset.tpp]||{}; c.prazo=sp.value.trim(); await salvar(sp.dataset.tpp); return condCliente(cnpj)}};
  box.onclick=async e=>{const b=e.target.closest('[data-tpu]'); if(!b) return; const r=b.dataset.tpu, u=ult[r], c=cfg[r]=cfg[r]||{}; if(u.prazo) c.prazo=u.prazo; const tt=tabDe(r,u.tabela); if(tt) c.tabela_id=tt.id; await salvar(r); condCliente(cnpj)}}

/* ================= Portal B2B: liberar acesso, tabelas e prazos por cliente ================= */
const B2B_URL='https://chamaeescritorio1-boop.github.io/medix-luvas/b2b/';
async function b2bCliente(cnpj,razao,fant){const box=$('#b2bbox'); if(!box) return; if(!cnpj){box.innerHTML='<p class="hint">Salve o cadastro primeiro.</p>';return}
  let A; try{A=await api(`b2b_acessos?select=*&cnpj=eq.${cnpj}&order=criado_em`)}catch(e){box.innerHTML='<p class="warn">Para ativar o portal, rode no Supabase o arquivo <b>7_portal_b2b.sql</b>.</p>';return}
  const R=(await reps(true)).filter(r=>r.ativa); const [CT,TA]=await Promise.all([api(`cliente_tabela?select=*&cnpj=eq.${cnpj}`).catch(()=>[]),api('tabelas?select=id,rep,nome,ativa,b2b_padrao&order=nome').catch(()=>[])]);
  const cfg={}; CT.forEach(c=>cfg[c.rep]={tabela_id:c.tabela_id,prazos:c.prazos||[],prazo:c.prazo||null});
  const msg=`Olá! Liberamos seu acesso ao portal de pedidos da Chamae. Entre em ${B2B_URL} com o e-mail EMAIL, toque em "Primeiro acesso? Criar minha senha" e pronto: você vê nossos catálogos com os seus preços e envia pedidos direto para nós.`;
  const card=r=>{const T=TA.filter(t=>t.rep===r.id&&t.ativa!==false); const pad=T.find(t=>t.b2b_padrao); const c=cfg[r.id]||{prazos:[]}; const pzR=((r.regras||{}).prazos||[]).map(p=>p.n); const todos=[...new Set([...pzR,...(c.prazos||[])])];
    return `<div class="card grid" style="background:var(--surface2)" data-rc="${r.id}"><div class="row" style="justify-content:space-between"><b>${repIcon(r,22)} ${esc(r.nome)}</b>${c.tabela_id||(c.prazos||[]).length?'<span class="tag ok">configurado</span>':''}</div>
     ${T.length?`<label class="f">Tabela de preço<select data-bt="${r.id}"><option value="">${pad?'Usar a padrão do portal ('+esc(pad.nome)+')':'— sem tabela (preço sob consulta) —'}</option>${T.map(t=>`<option value="${t.id}"${c.tabela_id==t.id?' selected':''}>${esc(t.nome)}${t.b2b_padrao?' ★':''}</option>`).join('')}</select></label>`:'<p class="hint" style="margin:0">Nenhuma tabela cadastrada para esta fábrica.</p>'}
     <div class="hint">Prazos liberados para este cliente ${c.prazos&&c.prazos.length?'':'(nenhum marcado = cliente vê todos os prazos da fábrica)'}</div>
     <div class="row">${todos.map(p=>`<button class="chip${(c.prazos||[]).includes(p)?' on':''}" data-bpz="${r.id}" data-v="${esc(p)}">${esc(p)}</button>`).join('')||'<span class="hint">A fábrica ainda não tem prazos cadastrados.</span>'}<input data-bpn="${r.id}" placeholder="+ outro prazo" style="width:150px;padding:6px"></div></div>`};
  box.innerHTML=`${A.map(a=>`<div class="row" style="justify-content:space-between;border-bottom:1px solid var(--line);padding:6px 0"><div><b>${esc(a.email)}</b> ${a.nome?'· '+esc(a.nome):''} ${a.ativo?'<span class="tag">ativo</span>':'<span class="tag bad">bloqueado</span>'}</div><div class="row"><button class="chip" data-bwa="${esc(a.email)}">Enviar convite</button><button class="chip" data-btog="${esc(a.email)}" data-on="${a.ativo?1:0}">${a.ativo?'Bloquear':'Liberar'}</button><button class="chip" data-bdel="${esc(a.email)}">✕</button></div></div>`).join('')||'<p class="hint">Nenhum acesso liberado.</p>'}
   <div class="row"><input id="bem" type="email" placeholder="E-mail do comprador" style="flex:2;min-width:200px"><input id="bno" placeholder="Nome (opcional)" style="flex:1;min-width:140px"><button class="btn sm" id="badd">Liberar acesso</button></div>
   <b style="margin-top:10px">Tabelas e prazos deste cliente em cada fábrica</b><p class="hint" style="margin:0">Vale para o portal e para os orçamentos do sistema. Salva sozinho ao escolher. ★ = tabela padrão do portal.</p>
   <div class="dgrid">${R.map(card).join('')}</div>
   <a class="btn sm ghost" href="${B2B_URL}" target="_blank" rel="noopener">Abrir o portal (visualizar como este cliente)</a>`;
  const salvar=async rep=>{const c=cfg[rep]||{prazos:[]}; try{if(!c.tabela_id&&!(c.prazos||[]).length&&!c.prazo) await api(`cliente_tabela?cnpj=eq.${cnpj}&rep=eq.${rep}`,{method:'DELETE'}); else await api('cliente_tabela?on_conflict=cnpj,rep',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({cnpj,rep,tabela_id:c.tabela_id||null,prazos:c.prazos||[]})}); toast('Salvo')}catch(err){toast(/prazos/.test(err.message)?'Rode o arquivo 9_prazos_cliente.sql no Supabase':'Erro: '+err.message)}};
  box.onclick=async e=>{const t=e.target; try{
    const pz=t.closest('[data-bpz]'); if(pz){const rep=pz.dataset.bpz, v=pz.dataset.v; const c=cfg[rep]=cfg[rep]||{tabela_id:null,prazos:[]}; c.prazos=c.prazos.includes(v)?c.prazos.filter(x=>x!==v):[...c.prazos,v]; pz.classList.toggle('on'); return salvar(rep)}
    if(t.id==='badd'){const em=box.querySelector('#bem').value.trim().toLowerCase(); if(!/@/.test(em)) return toast('E-mail inválido'); await api('b2b_acessos?on_conflict=email',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({email:em,cnpj,nome:box.querySelector('#bno').value.trim()||null,ativo:true})}); toast('Acesso liberado'); return b2bCliente(cnpj,razao,fant)}
    const w=t.closest('[data-bwa]'); if(w){const tx=msg.replace('EMAIL',w.dataset.bwa); try{await navigator.clipboard.writeText(tx)}catch(_){} window.open('https://wa.me/?text='+encodeURIComponent(tx),'_blank'); return toast('Convite copiado')}
    const tg=t.closest('[data-btog]'); if(tg){await api(`b2b_acessos?email=eq.${encodeURIComponent(tg.dataset.btog)}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({ativo:tg.dataset.on!=='1'})}); return b2bCliente(cnpj,razao,fant)}
    const d=t.closest('[data-bdel]'); if(d){if(!confirm('Remover este acesso?')) return; await api(`b2b_acessos?email=eq.${encodeURIComponent(d.dataset.bdel)}`,{method:'DELETE'}); return b2bCliente(cnpj,razao,fant)}}catch(err){toast('Erro: '+err.message)}};
  box.onchange=async e=>{const s2=e.target.closest('[data-bt]'); if(s2){const c=cfg[s2.dataset.bt]=cfg[s2.dataset.bt]||{prazos:[]}; c.tabela_id=s2.value?+s2.value:null; return salvar(s2.dataset.bt)}
    const n=e.target.closest('[data-bpn]'); if(n&&n.value.trim()){const rep=n.dataset.bpn; const c=cfg[rep]=cfg[rep]||{tabela_id:null,prazos:[]}; c.prazos=[...new Set([...c.prazos,n.value.trim()])]; await salvar(rep); b2bCliente(cnpj,razao,fant)}}}

/* ================= Equipe (gestor aprova acessos) ================= */
