/* ---------- importar contas a pagar do Conta Azul (relatório em PDF ou planilha) ---------- */
const CA_DRE=[[/simples|\bdas\b|imposto|\biss\b|\bpis\b|cofins|irpj|csll|parcelamento/i,'impostos','Deduções'],[/comiss/i,'com_vend','Pessoal'],
  [/sal[aá]rio|fgts|rescis|f[eé]rias|13[ºo°]|prev|inss|plano de sa[uú]de|odonto|vale|ticket|alimenta|pens[aã]o|pr[oó].?labore|benef|seguran[cç]a ocup|colaborador|funcion/i,'pessoal','Pessoal'],
  [/combust|ped[aá]gio|viage|hosped|brinde|amostra|feira|marketing|propaganda/i,'comercial','Comerciais'],[/tarifa|juros|\biof\b|multa|banc[aá]ri/i,'financeiro','Financeiras'],
  [/empr[eé]stimo|pronamp|financiamento|\bgiro\b/i,'emprestimo','Empréstimos'],[/transfer[eê]ncia/i,'transferencia','Transferências'],[/s[oó]cio|distribui|retirada/i,'retirada','Retiradas']];
const caDre=nome=>{for(const [re,d,g] of CA_DRE) if(re.test(nome)) return [d,g]; return ['administrativa','Administrativas']};
const caData=v=>{if(v==null||v==='') return null; if(typeof v==='number') return ymd(new Date(Math.round((v-25569)*864e5))); const s=String(v).trim(); let m=s.match(/^(\d{2})\/(\d{2})\/(\d{4})/); if(m) return `${m[3]}-${m[2]}-${m[1]}`; m=s.match(/^(\d{4})-(\d{2})-(\d{2})/); return m?m[0]:null};
const caNum=v=>typeof v==='number'?v:(lerNumBR(String(v||'').replace(/[R$\s]/g,'').replace(/^-/,''))||0)*(/^\s*-/.test(String(v||''))?-1:1);
async function caPDF(f){await loadPDFJS(); const pdf=await pdfjsLib.getDocument({data:await f.arrayBuffer()}).promise; const recs=[]; const DT=/^\d{2}\/\d{2}\/\d{4}$/, NUM=/^-?\d{1,3}(\.\d{3})*,\d{2}$/;
  for(let p=1;p<=pdf.numPages;p++){const pg=await pdf.getPage(p); const tc=await pg.getTextContent(), vp=pg.getViewport({scale:1}); /* posição na página como aparece (relatório em paisagem vem girado) */ const it=tc.items.filter(i=>i.str.trim()).map(i=>{const t=pdfjsLib.Util.transform(vp.transform,i.transform); return {s:i.str.trim(),x:t[4],y:-t[5]}});
    const hx=k=>{const h=it.find(i=>norm(i.s).startsWith(k)); return h&&h.x}; const H={desc:hx('DESCRI'),forn:hx('FORNECEDOR'),cat:hx('CATEGORIA'),val:hx('VALOR TOTAL')}; const hy=(it.find(i=>norm(i.s).startsWith('VENCIMENTO'))||{}).y;
    if(H.desc==null||H.cat==null||hy==null) continue; if(H.forn==null) H.forn=(H.desc+H.cat)/2; const fy=Math.max(...it.filter(i=>/^(Totais do per|Usu[aá]rio:)/i.test(i.s)).map(i=>i.y),-1e9);
    const linhas=[]; it.filter(i=>i.y<hy-2&&i.y>fy+2).sort((a,b)=>b.y-a.y||a.x-b.x).forEach(i=>{let l=linhas.find(l=>Math.abs(l.y-i.y)<2.5); if(!l){l={y:i.y,it:[]}; linhas.push(l)} l.it.push(i)});
    const reg=linhas.filter(l=>l.it.some(i=>DT.test(i.s)&&i.x<H.desc-2)).map(l=>({l,extra:[]})); if(!reg.length) continue;
    linhas.filter(l=>!reg.some(r=>r.l===l)).forEach(l=>{const r=reg.reduce((a,b)=>Math.abs(b.l.y-l.y)<Math.abs(a.l.y-l.y)?b:a); r.extra.push(l)});
    const col=(a,b,ls)=>ls.flatMap(x=>x.it.filter(i=>i.x>=a-3&&i.x<b-3&&!NUM.test(i.s)&&!DT.test(i.s)).map(i=>i.s)).join(' ').replace(/\s+/g,' ').trim();
    /* texto quebrado na virada da página: as linhas soltas no topo pertencem à última conta da página anterior */
    const r0=reg[0], ac=r0.extra.filter(x=>x.y>r0.l.y).sort((a,b)=>b.y-a.y), ab=r0.extra.filter(x=>x.y<r0.l.y).length; const ant=recs[recs.length-1];
    if(ant&&ac.length>ab){const mv=ac.slice(0,ac.length-ab); r0.extra=r0.extra.filter(x=>!mv.includes(x)); const j=(k,a,b)=>{const t=col(a,b,mv); if(t) ant[k]=(ant[k]+' '+t).trim()}; j('desc',H.desc,H.forn); j('forn',H.forn,H.cat); j('cat',H.cat,H.val!=null?H.val:1e4)}
    for(const {l,extra} of reg){const todas=[l,...extra].sort((a,b)=>b.y-a.y);
      const ds=l.it.filter(i=>DT.test(i.s)).sort((a,b)=>a.x-b.x).map(i=>i.s), ns=l.it.filter(i=>NUM.test(i.s)).sort((a,b)=>a.x-b.x).map(i=>i.s);
      const semValor=todas.filter(x=>x===l||!x.it.some(i=>NUM.test(i.s))); let cat=col(H.cat,H.val!=null?H.val:1e4,semValor); if(!cat){const c1=extra.filter(x=>x.it.some(i=>NUM.test(i.s))).sort((a,b)=>b.y-a.y)[0]; if(c1) cat=col(H.cat,H.val!=null?H.val:1e4,[c1])}
      const sit=(l.it.find(i=>/^(pago|em aberto|vencid|atrasad|cancel|recebid|parcial)/i.test(i.s))||{}).s||'';
      recs.push({venc:caData(ds[0]),pag:ds[1]?caData(ds[1]):null,desc:col(H.desc,H.forn,todas),forn:col(H.forn,H.cat,todas),cat,valor:caNum(ns[0]),aberto:ns[1]!=null?caNum(ns[1]):null,sit})}}
  return recs}
async function caXLS(f){await loadXLSX(); const wb=XLSX.read(await f.arrayBuffer(),{type:'array'}); const out=[];
  for(const sn of wb.SheetNames){const A=XLSX.utils.sheet_to_json(wb.Sheets[sn],{header:1,raw:true,defval:''}); const hi=A.findIndex(r=>r.some(c=>/vencimento/i.test(String(c)))); if(hi<0) continue;
    const h=A[hi].map(c=>norm(c)); const ix=(re,not)=>h.findIndex(c=>re.test(c)&&!(not&&not.test(c)));
    const C={venc:ix(/VENCIMENTO/),pag:ix(/PAGAMENTO|PAGO EM|DATA DO PAG|DATA DE PAG/,/FORMA/),desc:ix(/DESCRI/),forn:ix(/FORNECEDOR|CONTATO|NOME DO/),cat:ix(/CATEGORIA/),valor:[ix(/VALOR TOTAL|VALOR ORIGINAL|VALOR DA PARCELA/,/ABERTO/),ix(/^VALOR/,/ABERTO|PAGO|JUROS|MULTA|DESCONTO|CATEGORIA/),ix(/^VALOR/,/ABERTO/)].find(i=>i>=0)??-1,aberto:ix(/ABERTO/),sit:ix(/SITUA|STATUS/)};
    A.slice(hi+1).forEach(r=>{const g=k=>C[k]>=0?r[C[k]]:''; const venc=caData(g('venc')); if(!venc) return; out.push({venc,pag:caData(g('pag')),desc:String(g('desc')).trim(),forn:String(g('forn')).trim(),cat:String(g('cat')).trim(),valor:Math.abs(caNum(g('valor'))),aberto:C.aberto>=0?Math.abs(caNum(g('aberto'))):null,sit:String(g('sit')).trim()})})}
  return out}
async function finImportarCA(files){let R=[]; const err=[];
  for(const f of files){try{R.push(.../\.pdf$/i.test(f.name)?await caPDF(f):await caXLS(f))}catch(e){err.push(f.name+': '+e.message)}}
  R=R.filter(r=>r.venc&&r.valor&&r.desc); if(!R.length) return toast('Não encontrei lançamentos'+(err.length?': '+err.join('; '):' nesses arquivos'));
  await finDados(true); const catPor=n=>FIN.cats.find(c=>c.tipo==='P'&&norm(c.nome)===norm(n));
  const novas={}; R.forEach(r=>{r.cat=r.cat||'Outras despesas'; if(!catPor(r.cat)&&!novas[norm(r.cat)]){const [dre,grupo]=caDre(r.cat); novas[norm(r.cat)]={nome:r.cat,dre,grupo}}});
  const de=R.reduce((a,r)=>r.venc<a?r.venc:a,'9999'), ate=R.reduce((a,r)=>r.venc>a?r.venc:a,'0000');
  const ex=await api(`fin_lancamentos?select=descricao,valor,vencimento&tipo=eq.P&vencimento=gte.${de}&vencimento=lte.${ate}`); const chave=r=>r.vencimento+'|'+norm(r.descricao)+'|'+(+r.valor).toFixed(2); const ja=new Set(ex.map(chave));
  R.forEach(r=>r.dup=ja.has(chave({vencimento:r.venc,descricao:r.desc,valor:r.valor}))); const nv=R.filter(r=>!r.dup), pago=r=>/pago|quitad|liquid/i.test(r.sit)||(r.aberto===0&&!!r.pag);
  const opts=FDRE.filter(([k])=>!k.startsWith('=')&&!['receita','outras_receitas'].includes(k));
  const ov=document.createElement('div'); ov.className='ov'; ov.innerHTML=`<div class="sh grid"><b style="font-size:18px">Importar contas a pagar (Conta Azul)</b>
   <p class="hint">${R.length} lançamento(s) de ${dbr(de)} a ${dbr(ate)} · <b>${nv.length} novo(s)</b>${R.length-nv.length?` · ${R.length-nv.length} já estão no Sistema (não duplica)`:''} · total novo ${brl(nv.reduce((a,r)=>a+r.valor,0))}${err.length?`<br><span class="warn">${esc(err.join('; '))}</span>`:''}</p>
   ${Object.keys(novas).length?`<div class="card"><b>Categorias novas</b> <span class="hint">confira em qual linha da DRE cada uma entra</span><table class="t" style="margin-top:6px">${Object.entries(novas).map(([k,c])=>`<tr><td>${esc(c.nome)}</td><td><select data-nc="${esc(k)}">${opts.map(([d,l])=>`<option value="${d}"${d===c.dre?' selected':''}>${l}</option>`).join('')}</select></td></tr>`).join('')}</table></div>`:''}
   <div style="overflow:auto;max-height:45vh"><table class="t"><tr><th>Vencimento</th><th>Descrição</th><th>Fornecedor</th><th>Categoria</th><th class="n">Valor</th><th>Situação</th></tr>${R.map(r=>`<tr style="border-top:1px solid var(--line);${r.dup?'opacity:.45':''}"><td>${dbr(r.venc)}</td><td>${esc(r.desc)}${r.dup?' <span class="tag">já existe</span>':''}</td><td class="hint">${esc(r.forn)}</td><td class="hint">${esc(r.cat)}</td><td class="n">${brl(r.valor)}</td><td>${pago(r)?`pago ${dbr(r.pag)}`:'em aberto'}</td></tr>`).join('')}</table></div>
   <div class="row"><button class="btn" id="caok"${nv.length?'':' disabled'}>Importar ${nv.length} lançamento(s)</button><button class="btn ghost" data-x>Cancelar</button></div></div>`;
  document.body.appendChild(ov); ov.onchange=e=>{const s=e.target.closest('[data-nc]'); if(s) novas[s.dataset.nc].dre=s.value};
  ov.onclick=async e=>{const t=e.target; if(t===ov||t.closest('[data-x]')) return ov.remove(); if(t.id!=='caok') return; t.disabled=true; t.textContent='Importando…';
    try{const NG={impostos:'Deduções',pessoal:'Pessoal',com_vend:'Pessoal',comercial:'Comerciais',administrativa:'Administrativas',financeiro:'Financeiras',emprestimo:'Empréstimos',transferencia:'Transferências',investimento:'Investimentos',retirada:'Retiradas'};
      const cs=Object.values(novas).map(c=>({id:'ca_'+norm(c.nome).toLowerCase().replace(/[^a-z0-9]+/g,'_').slice(0,40),tipo:'P',grupo:NG[c.dre]||c.grupo,nome:c.nome,dre:c.dre,ordem:600}));
      if(cs.length) await api('fin_categorias?on_conflict=id',{method:'POST',headers:{Prefer:'resolution=ignore-duplicates,return=minimal'},body:JSON.stringify(cs)}); await finDados(true);
      const rows=nv.map(r=>{const p=pago(r), pm=r.desc.match(/^(\d{1,3}\/\d{1,3})\s*-/); return {tipo:'P',descricao:r.desc,categoria:(catPor(r.cat)||{}).id||'outras_desp',valor:r.valor,vencimento:r.venc,competencia:r.venc.slice(0,8)+'01',status:p?'pago':'aberto',pago_em:p?(r.pag||r.venc):null,valor_pago:p?r.valor:null,cliente:r.forn||null,parcela:pm?pm[1]:null,obs:'Importado do Conta Azul'}});
      for(let k=0;k<rows.length;k+=200) await api('fin_lancamentos',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify(rows.slice(k,k+200))});
      ov.remove(); toast(`${rows.length} lançamento(s) importado(s)`); const [y,mo]=de.split('-'); FST.y=+y; FST.mo=+mo-1; FST.st=''; finView()}catch(err){t.disabled=false; t.textContent='Tentar de novo'; toast('Erro: '+err.message)}}}

/* ---------- DRE ---------- */
async function finDRE(box){const y=FST.y, cx=FST.dre==='caixa'; const L1=await api(`fin_lancamentos?select=tipo,categoria,valor,valor_pago,competencia,vencimento,pago_em,status&status=neq.cancelado&${cx?`pago_em=gte.${y}-01-01&pago_em=lte.${y}-12-31&status=eq.pago`:`competencia=gte.${y}-01-01&competencia=lte.${y}-12-31`}`); if(!box.isConnected) return;
  const V={}; L1.forEach(l=>{const d=cx?l.pago_em:(l.competencia||l.vencimento); const mo=+d.slice(5,7)-1; const k=finCat(l.categoria).dre||(l.tipo==='R'?'outras_receitas':'administrativa'); const val=(cx?+l.valor_pago||0:+l.valor||0)*(l.tipo==='R'?1:-1); V[k]=V[k]||Array(12).fill(0); V[k][mo]+=val});
  const g=k=>V[k]||Array(12).fill(0), som=(...ks)=>Array.from({length:12},(_,i)=>ks.reduce((a,k)=>a+g(k)[i],0));
  const T={'=liq':som('receita','outras_receitas','impostos')}; T['=mc']=som('receita','outras_receitas','impostos','com_vend'); T['=op']=som('receita','outras_receitas','impostos','com_vend','pessoal','comercial','administrativa'); T['=res']=som('receita','outras_receitas','impostos','com_vend','pessoal','comercial','administrativa','financeiro');
  const cols=Array.from({length:12},(_,i)=>i);
  const cel=v=>`<td class="n${v<0?' bad':''}">${v?brl(v).replace('R$','').trim():'—'}</td>`;
  box.innerHTML=`<div class="row" style="margin-bottom:10px"><button class="chip${cx?'':' on'}" data-fdr="comp">Competência</button><button class="chip${cx?' on':''}" data-fdr="caixa">Caixa (pelo que foi baixado)</button><span class="hint">Ano ${y} · ${cx?'pela data da baixa':'comissão no mês do faturamento, despesas no mês de competência'}</span><span style="flex:1"></span><button class="btn ghost sm" id="fdx">Excel</button></div>
   <div style="overflow-x:auto"><table class="t"><tr><th></th>${cols.map(i=>`<th class="n">${MESES[i].slice(0,3)}</th>`).join('')}<th class="n">Ano</th></tr>
   ${FDRE.map(([k,l])=>{const a=k.startsWith('=')?T[k]:g(k); const tot=a.reduce((s,v)=>s+v,0); return `<tr style="border-top:1px solid var(--line);${k.startsWith('=')?'font-weight:700;background:var(--surface2)':''}${['investimento','retirada','emprestimo','transferencia'].includes(k)?'color:var(--muted)':''}"><td style="white-space:nowrap">${l}</td>${cols.map(i=>cel(a[i])).join('')}${cel(tot)}</tr>`}).join('')}</table></div>
   <p class="hint" style="margin-top:8px">Cada categoria do plano de contas cai numa linha da DRE (Configurar › Plano de contas). Impostos entram pelo lançamento da guia em Contas a pagar.</p>`;
  box.onclick=async e=>{const b=e.target.closest('[data-fdr]'); if(b){FST.dre=b.dataset.fdr; return finDRE(box)}
    if(e.target.id==='fdx'){await loadXLSX(); const ws=XLSX.utils.aoa_to_sheet([['DRE '+y+(cx?' (caixa)':' (competência)'),...cols.map(i=>MESES[i]),'Ano'],...FDRE.map(([k,l])=>{const a=k.startsWith('=')?T[k]:g(k); return [l,...cols.map(i=>Math.round(a[i]*100)/100),Math.round(a.reduce((s,v)=>s+v,0)*100)/100]})]); const wb=XLSX.utils.book_new(); XLSX.utils.book_append_sheet(wb,ws,'DRE'); XLSX.writeFile(wb,`DRE_${y}.xlsx`)}}}

/* ---------- configurar: comissão por representada, contas bancárias, plano de contas ---------- */
